package edu.uiu.aoop.careerforge.service;
import edu.uiu.aoop.careerforge.model.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class WeightedJobMatchingStrategy implements JobMatchingStrategy {
 public MatchResult score(StudentProfile p,Job job,List<String> skills){if(p==null)return new MatchResult(0,List.of(),List.of(),List.of("Complete your profile to receive a match"));String target=Optional.ofNullable(p.getTargetRole()).orElse("").toLowerCase();String title=job.getTitle().toLowerCase();String location=Optional.ofNullable(p.getLocation()).orElse("").toLowerCase();int role=target.isBlank()?0:(title.contains(target)||target.contains(title)?15:4);int place=location.isBlank()?0:(job.getWorkplaceType().equalsIgnoreCase("Remote")||Optional.ofNullable(job.getLocation()).orElse("").toLowerCase().contains(location)?10:2);int profile=(int)Math.round(Optional.ofNullable(p.getProfileCompletion()).orElse(0d)/20d);int skill=Math.min(60,skills.size()*12);int total=Math.min(100,role+place+profile+skill);List<String> reasons=new ArrayList<>();if(role>4)reasons.add("Your target role aligns with this opportunity");if(place==10)reasons.add("The work mode matches your location preference");if(skill>0)reasons.add("Your saved skills improve this recommendation");if(reasons.isEmpty())reasons.add("Add career details and skills to improve this match");return new MatchResult(total,skills,List.of(),reasons);}
}
